if (!msg.payload.messages) return {payload: 'healthy'};
for (const spec of msg.payload.messages) {
  const text = spec.unit.repeat(spec.repeat) + (spec.suffix || '');
  for (let i = 0; i < (spec.copies || 1); i++) {
    node.error(spec.kind === 'object' ? {message: text} : spec.kind === 'error' ? new Error(text) : text, msg);
    node.send({payload: text.length});
  }
}
return null;
